        runs = []
        start = None
        for r in range(h + 1):
            yes = r < h and grid[r][c] != 5 and grid[r][c] != 8
            if yes and start is None:
                start = r
            if not yes and start is not None:
                runs.append((start, r - 1, grid[start][c]))
                start = None
        edge_bars.extend((c, a, b, color) for a, b, color in runs)
    # Find matching-length bars at opposite edges; markers in either band
    # activate the corresponding relative row in both bands.
    pairs = []
    for i, first in enumerate(edge_bars):
        for second in edge_bars[i + 1:]:
            c1, a1, b1, _ = first
            c2, a2, b2, _ = second
            if c1 != c2 and b1 - a1 == b2 - a2:
                pairs.append((first, second))
    paired_bands = set()
    for one, two in pairs:
        paired_bands.add((one[0], one[1], one[2]))
        paired_bands.add((two[0], two[1], two[2]))
        marker_rows = set()
