                        marker_cells.append((r, x, grid[r][x]))
        if not marker_rows:
            continue
        for c, a, b, _ in (one, two):
            for off in marker_rows:
                r = a + off
                # In a marker row, fill toward the opposite edge. In the
                # echo band, fill the entire interior up to the edge bar.
                marks_here = [(x, v) for rr, x, v in marker_cells if rr == r]
                if marks_here:
                    x, v = marks_here[0]
                    out[r][x] = 4
                    for xx in range(x + 1, w):
                        if grid[r][xx] in (5, 8):
                            out[r][xx] = v
                else:
                    for xx in range(w):
                        if xx != c and grid[r][xx] in (5, 8):
                            out[r][xx] = marker_color
    # General marker rays, including cases without paired bands.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v in (0, 5, 8):
                continue
            if c not in (0, w - 1):
                out[r][c] = 4
                for x in range(c + 1, w):
                    if grid[r][x] in (5, 8):
                        out[r][x] = v
    return out

if __name__ == '__main__':
