def _runs(values, background):
    runs = []
    start = None
    for i in range(len(values) + 1):
        active = i < len(values) and values[i] != background
        if active and start is None:
            start = i
        elif not active and start is not None:
            runs.append((start, i - 1, values[start]))
            start = None
    return runs


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Boundary objects, indexed by side; run coordinates are along the edge.
    bars = {
        'top': _runs(grid[0], background),
        'bottom': _runs(grid[-1], background),
        'left': _runs([grid[r][0] for r in range(h)], background),
        'right': _runs([grid[r][-1] for r in range(h)], background),
    }
    border_colors = {color for runs in bars.values() for _, _, color in runs}
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != background and grid[r][c] not in border_colors]

    def in_bar(side, r, c, run):
        a, b, _ = run
        if side == 'top': return r == 0 and a <= c <= b
        if side == 'bottom': return r == h - 1 and a <= c <= b
        if side == 'left': return c == 0 and a <= r <= b
        return c == w - 1 and a <= r <= b

    # Marker rays extend from the marker toward the edge bar that spans its
    # coordinate; the marker itself changes to 4.
    for r, c, color in markers:
        out[r][c] = 4
        if any(a <= c <= b for a, b, _ in bars['top']):
            for rr in range(r - 1, -1, -1):
                out[rr][c] = color
        elif any(a <= c <= b for a, b, _ in bars['bottom']):
            for rr in range(r + 1, h):
                out[rr][c] = color
        elif any(a <= r <= b for a, b, _ in bars['left']):
            for cc in range(c - 1, -1, -1):
                out[r][cc] = color
        elif any(a <= r <= b for a, b, _ in bars['right']):
            for cc in range(c + 1, w):
                out[r][cc] = color

    # A marker offset in one edge bar activates the matching offset in an
    # equal-length opposite bar; extend inward from that bar in marker color.
    for first, opposite, axis in (('top', 'bottom', 'vertical'), ('bottom', 'top', 'vertical'),
