 "content": "from collections import Counter


def _segments(values, bg):
    result, start = [], None
    for i in range(len(values) + 1):
        active = i < len(values) and values[i] != bg
        if active and start is None:
            start = i
        elif not active and start is not None:
            result.append((start, i - 1, values[start]))
            start = None
    return result


def transform(grid):
    """Project interior marker rays along the aligned edge-bar axis."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bars = {
        'left': _segments([grid[r][0] for r in range(h)], bg),
        'right': _segments([grid[r][-1] for r in range(h)], bg),
        'top': _segments(grid[0], bg),
        'bottom': _segments(grid[-1], bg),
    }
    bar_colors = {color for segs in bars.values() for _, _, color in segs}
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] not in bar_colors
               and r not in (0, h - 1) and c not in (0, w - 1)]

    # Horizontal bars mark rows; vertical bars mark columns. A marker changes
    # to 4. It paints the interior segment from its position to the nearest
    # perpendicular bar in its aligned row/column, without replacing bars.
    for r, c, color in markers:
        out[r][c] = 4
        left_aligned = any(a <= r <= b for a, b, _ in bars['left'])
        right_aligned = any(a <= r <= b for a, b, _ in bars['right'])
        top_aligned = any(a <= c <= b for a, b, _ in bars['top'])
        bottom_aligned = any(a <= c <= b for a, b, _ in bars['bottom'])
        if left_aligned:
            for x in range(c + 1, w):
                if grid[r][x] in bar_colors:
                    break
                out[r][x] = color
        elif right_aligned:
            for x in range(c - 1, -1, -1):
                if grid[r][x] in bar_colors:
                    break
                out[r][x] = color
        elif top_aligned:
            for y in range(r + 1, h):
                if grid[y][c] in bar_colors:
                    break
                out[y][c] = color
        elif bottom_aligned:
            for y in range(r - 1, -1, -1):
                if grid[y][c] in bar_colors:
                    break
                out[y][c] = color
    return out


if __name__ == '__main__':
    pass
